WITH unified_returns AS ( SELECT cr.cr_returning_customer_sk AS returning_customer_sk, cr.cr_returning_addr_sk AS returning_addr_sk, cr.cr_returning_hdemo_sk AS returning_hdemo_sk, cr.cr_net_loss AS net_loss, cr.cr_return_quantity AS return_qty, cr.cr_return_amount AS return_amt FROM catalog_returns cr UNION ALL SELECT wr.wr_returning_customer_sk, wr.wr_returning_addr_sk, wr.wr_returning_hdemo_sk, wr.wr_net_loss, wr.wr_return_quantity, wr.wr_return_amt FROM web_returns wr ), customer_agg AS ( SELECT returning_customer_sk, returning_addr_sk, returning_hdemo_sk, SUM(net_loss) AS total_net_loss, SUM(return_qty) AS total_return_qty, AVG(return_amt) AS avg_return_amt FROM unified_returns GROUP BY returning_customer_sk, returning_addr_sk, returning_hdemo_sk ) SELECT ca.ca_city, ca.ca_state, hd.hd_income_band_sk, ca.ca_zip, ca.ca_country, cust.returning_customer_sk, cust.total_net_loss, cust.total_return_qty, cust.avg_return_amt, CASE WHEN cust.total_net_loss > 5000 THEN 'HIGH_LOSS' ELSE 'NORMAL' END AS loss_flag, DENSE_RANK() OVER (ORDER BY cust.total_net_loss DESC) AS loss_rank FROM customer_agg cust JOIN customer_address ca ON cust.returning_addr_sk = ca.ca_address_sk JOIN household_demographics hd ON cust.returning_hdemo_sk = hd.hd_demo_sk ORDER BY loss_rank LIMIT 10
